WITH "closed" AS (UPDATE "alerts" AS "straggler" SET "resolved_at" = date_trunc('milliseconds', now()) WHERE "straggler"."kind" = 'exception_share_second_month_at_risk' AND "straggler"."resolved_at" IS NULL AND EXISTS (SELECT 1 FROM "alerts" AS "current" WHERE "current"."kind" = 'second_non_compliant_month_at_risk' AND "current"."scope" = "straggler"."scope" AND "current"."resolved_at" IS NULL) RETURNING "straggler"."id", "straggler"."resolved_at") INSERT INTO "audit_log" ("entity", "entity_id", "actor_id", "at", "previous_value", "new_value") SELECT 'alert', "id", NULL, "resolved_at", '{"resolvedAt": null}'::jsonb, jsonb_build_object('resolvedAt', to_char("resolved_at" AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) FROM "closed";--> statement-breakpoint
UPDATE "alerts" SET "detail" = "detail" || '{"previousMonthNonCompliantOn": ["exception_share"], "contingencyShareTenthsOfPercent": null, "contingencyNonCompliancePercent": 5}'::jsonb WHERE "kind" = 'exception_share_second_month_at_risk' AND NOT ("detail" ? 'previousMonthNonCompliantOn');--> statement-breakpoint
UPDATE "alerts" SET "detail" = "detail" - 'shareTenthsOfPercent' - 'nonCompliancePercent' || jsonb_build_object('exceptionShareTenthsOfPercent', "detail" -> 'shareTenthsOfPercent', 'exceptionShareNonCompliancePercent', "detail" -> 'nonCompliancePercent') WHERE "kind" = 'exception_share_second_month_at_risk' AND "detail" ? 'shareTenthsOfPercent';--> statement-breakpoint
UPDATE "alerts" SET "kind" = 'second_non_compliant_month_at_risk' WHERE "kind" = 'exception_share_second_month_at_risk';
